1	// Kernel 5: row-parallel Q1_0 gemv built on nds.vd4dots.vv (XAndesVDot).
2	//
3	// nds.vd4dots.vv vd, vs1, vs2 with vtype e32: for every i32 lane,
4	//   vd[lane] += sum_{k=0..3} vs1[4*lane+k] * vs2[4*lane+k]   (int8 x int8)
5	// Verified on QEMU -cpu andes-ax45mpv. GCC 14.2 has no intrinsic for it, so
6	// it goes in as inline asm; GCC re-emits its own vsetvli afterwards, so the
7	// asm may set vtype freely.
8	//
9	// Layout difference vs kernel 3: a lane must hold 4 consecutive columns of
10	// ONE row, so the sign plane is grouped 4 columns at a time (see q1_0.h).
11	
12	#include "q1_0.h"
13	
14	#include <assert.h>
15	#include <string.h>
16	
17	#include <riscv_vector.h>
