23	void q1_0_repack_64d4(const block_q1_0 * src, block_q1_0_64d4 * dst, int nr, int n) {
24	    const int nb = n / QK1_0;
25	    assert(nr % Q1_NX1_N == 0);
26	    assert(n % QK1_0 == 0);
27	
28	    memset(dst, 0, (size_t)(nr / Q1_NX1_N) * nb * sizeof(block_q1_0_64d4));
29	
30	    for (int r = 0; r < nr; ++r) {
31	        const int g = r / Q1_NX1_N;
32	        const int j = r % Q1_NX1_N;
33	        for (int ib = 0; ib < nb; ++ib) {
34	            const block_q1_0 * b = &src[(size_t)r * nb + ib];
35	            block_q1_0_64d4  * o = &dst[(size_t)g * nb + ib];
36	            o->d[j] = b->d;
37	            for (int c = 0; c < QK1_0; ++c) {
38	                const uint8_t bit = (b->qs[c / 8] >> (c % 8)) & 1;
39	                const int idx = 4 * j + (c % 4);            // bit slot in the plane
40	                o->qs[c / 4][idx / 8] |= (uint8_t)(bit << (idx % 8));
41	            }
42	        }
43	    }
44	}
