// ---- Q1_0 row-parallel 64x1 (F4d) -----------------------------------------
// lane j = row j. Per column: sign bit selects +-activation; int sums per
// 32-group, scaled by the q8 dy, then by the per-row q1 dx per block - the
// same two-level order as ggml_vec_dot_q1_0_q8_0, so results match closely.

void ggml_gemv_q1_0_64x1_q8_0_generic(int n, float * GGML_RESTRICT s, size_t bs, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy, int nr, int nc) {
    const int qk = QK8_0;
    const int nb = n / QK1_0;
    assert(n % QK1_0 == 0);
    assert(nc % 64 == 0);
    UNUSED(bs); UNUSED(nr);

    const block_q8_0 * a_ptr = (const block_q8_0 *) vy;
    for (int x = 0; x < nc / 64; ++x) {
        const block_q1_0x64 * b_ptr = (const block_q1_0x64 *) vx + (size_t) x * nb;

        float sumf[64] = { 0.0f };
        for (int l = 0; l < nb; ++l) {
            float acc[64] = { 0.0f };
            for (int k = 0; k < QK1_0 / qk; ++k) {
                const block_q8_0 * ab = &a_ptr[l * (QK1_0 / qk) + k];
                const float dy = GGML_CPU_FP16_TO_FP32(ab->d);

                int sumi[64] = { 0 };
                for (int c = 0; c < qk; ++c) {
                    const int v = ab->qs[c];
                    const uint8_t * bits = b_ptr[l].qs[k * qk + c];
                    for (int j = 0; j < 64; ++j) {
                        sumi[j] += ((bits[j / 8] >> (j % 8)) & 1) ? v : -v;
                    }
                }
                for (int j = 0; j < 64; ++j) {
                    acc[j] += dy * (float) sumi[j];
                }
            }
            for (int j = 0; j < 64; ++j) {
                sumf[j] += GGML_CPU_FP16_TO_FP32(b_ptr[l].d[j]) * acc[j];
            }
        }
        for (int j = 0; j < 64; ++j) {
            s[x * 64 + j] = sumf[j];
        }
    }
}

void ggml_gemm_q1_0_64x1_q8_0_generic(int n, float * GGML_RESTRICT s, size_t bs, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy, int nr, int nc) {
    const int qk   = QK8_0;
    const int nb   = n / QK1_0;
    const int nbq8 = n / qk;
    assert(n % QK1_0 == 0);
    assert(nr % 4 == 0);
    assert(nc % 64 == 0);

    for (int y = 0; y < nr / 4; ++y) {
        // activations: 4 rows interleaved byte-wise (blck_size_interleave 1)
        const block_q8_0x4 * a_ptr = (const block_q8_0x4 *) vy + (size_t) y * nbq8;

        for (int x = 0; x < nc / 64; ++x) {
            const block_q1_0x64 * b_ptr = (const block_q1_0x64 *) vx + (size_t) x * nb;

            float sumf[4][64] = { { 0.0f } };
            for (int l = 0; l < nb; ++l) {
                float acc[4][64] = { { 0.0f } };
                for (int k = 0; k < QK1_0 / qk; ++k) {
                    const block_q8_0x4 * ab = &a_ptr[l * (QK1_0 / qk) + k];
                    float dy[4];
                    for (int m = 0; m < 4; ++m) {
                        dy[m] = GGML_CPU_FP16_TO_FP32(ab->d[m]);
                    }

                    int sumi[4][64] = { { 0 } };
                    for (int c = 0; c < qk; ++c) {
                        const uint8_t * bits = b_ptr[l].qs[k * qk + c];
                        for (int m = 0; m < 4; ++m) {
                            const int v = ab->qs[c * 4 + m];
                            for (int j = 0; j < 64; ++j) {
                                sumi[m][j] += ((bits[j / 8] >> (j % 8)) & 1) ? v : -v;
                            }
                        }
                    }
                    for (int m = 0; m < 4; ++m) {
                        for (int j = 0; j < 64; ++j) {
                            acc[m][j] += dy[m] * (float) sumi[m][j];
                        }
                    }
                }
                for (int m = 0; m < 4; ++m) {
                    for (int j = 0; j < 64; ++j) {
                        sumf[m][j] += GGML_CPU_FP16_TO_FP32(b_ptr[l].d[j]) * acc[m][j];
                    }
                }
            }
            for (int m = 0; m < 4; ++m) {
