56	static inline vfloat32m2_t d4_expand_fp16_64(const ggml_half * p) {
57	    const size_t vl = Q1_NX1_N;
58	    const vuint16m1_t vh = __riscv_vle16_v_u16m1(p, vl);
59	    const vuint32m2_t hz = __riscv_vzext_vf2_u32m2(vh, vl);
60	    const vuint32m2_t sign = __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x8000, vl), 16, vl);
61	    vuint32m2_t mag = __riscv_vadd_vx_u32m2(
62	        __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x7FFF, vl), 13, vl),
63	        (uint32_t)112 << 23, vl);
64	    const vbool16_t ez = __riscv_vmseq_vx_u32m2_b16(__riscv_vand_vx_u32m2(hz, 0x7C00, vl), 0, vl);
65	    mag = __riscv_vmerge_vxm_u32m2(mag, 0, ez, vl);
66	    return __riscv_vreinterpret_v_u32m2_f32m2(__riscv_vor_vv_u32m2(sign, mag, vl));
67	}
