110	// ---- v2: one asm block per 16 columns -------------------------------------
111	// v1 pays 4 vsetvli per 4 columns (GCC flips e8 <-> e32 around every step) and
112	// chains all 8 dots of a group through one accumulator. v2 does the four
113	// mask+merge steps in e8, flips once, then the four dots in e32, and splits
114	// the dots over two accumulators. Internal registers are fixed and clobbered;
115	// the accumulators stay compiler-allocated so they live across the block loop.
116	//   v0 mask | v2 -1 | v4,v6,v8,v10 weights | v12,v14,v16,v18 activations
117	#define D4_TILE16(acc0, acc1, planes, acts)                                \
118	    asm volatile(                                                          \
119	        "vsetvli t0, zero, e8, m2, ta, ma\n\t"                             \
120	        "mv      t1, %2\n\t"                                               \
121	        "vmv.v.i v2, -1\n\t"                                               \
122	        "vlm.v   v0, (t1)\n\t"                                             \
123	        "vmerge.vim v4, v2, 1, v0\n\t"                                     \
124	        "addi    t1, t1, 32\n\t"                                           \
125	        "vlm.v   v0, (t1)\n\t"                                             \
126	        "vmerge.vim v6, v2, 1, v0\n\t"                                     \
127	        "addi    t1, t1, 32\n\t"                                           \
128	        "vlm.v   v0, (t1)\n\t"                                             \
129	        "vmerge.vim v8, v2, 1, v0\n\t"                                     \
130	        "addi    t1, t1, 32\n\t"                                           \
131	        "vlm.v   v0, (t1)\n\t"                                             \
132	        "vmerge.vim v10, v2, 1, v0\n\t"                                    \
133	        "vsetvli t0, zero, e32, m2, ta, ma\n\t"                            \
134	        "mv      t2, %3\n\t"                                               \
135	        "vlse32.v v12, (t2), zero\n\t"                                     \
136	        "addi    t2, t2, 4\n\t"                                            \
137	        "vlse32.v v14, (t2), zero\n\t"                                     \
138	        "addi    t2, t2, 4\n\t"                                            \
139	        "vlse32.v v16, (t2), zero\n\t"                                     \
140	        "addi    t2, t2, 4\n\t"                                            \
141	        "vlse32.v v18, (t2), zero\n\t"                                     \
142	        "nds.vd4dots.vv %0, v4,  v12\n\t"                                  \
143	        "nds.vd4dots.vv %1, v6,  v14\n\t"                                  \
144	        "nds.vd4dots.vv %0, v8,  v16\n\t"                                  \
145	        "nds.vd4dots.vv %1, v10, v18"                                      \
146	        : "+vr"(acc0), "+vr"(acc1)                                         \
147	        : "r"(planes), "r"(acts)                                           \
148	        : "t0", "t1", "t2",                                                \
149	          "v0", "v2", "v4", "v6", "v8", "v10", "v12", "v14", "v16", "v18")
