161	        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
162	
163	        for (int ib = 0; ib < nb; ++ib) {
164	            const vfloat32m2_t dx = d4_expand_fp16_64(bx[ib].d);
165	            vfloat32m2_t facc = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
166	
167	            for (int k = 0; k < 4; ++k) {
168	                const block_q8_0 * yb = &y[ib * 4 + k];
169	                const float dy = lab_fp16_to_fp32(yb->d);
170	
171	                const int8_t * aq = ya + (ib * 4 + k) * QK8_0;
172	                vint32m2_t acc0 = __riscv_vmv_v_x_i32m2(0, vl32);
173	                vint32m2_t acc1 = acc0;
174	                D4_TILE16(acc0, acc1, &bx[ib].qs[k * (QK8_0 / 4)][0],     aq);
175	                D4_TILE16(acc0, acc1, &bx[ib].qs[k * (QK8_0 / 4) + 4][0], aq + 16);
176	
177	                const vint32m2_t acc = __riscv_vadd_vv_i32m2(acc0, acc1, vl32);
178	                facc = __riscv_vfmacc_vf_f32m2(facc, dy, __riscv_vfcvt_f_x_v_f32m2(acc, vl32), vl32);
179	            }
180	            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl32);
181	        }
182	        __riscv_vse32_v_f32m2(s + (size_t)g * Q1_NX1_N, sumf, vl32);
183	    }
184	}
185	
186	// ---- isolation legs: which of the four shared ops costs the cycles? --------
187	// v2 and v1 differ 3.4x in instruction count but run at the same speed, so the
188	// cost sits in what they share per 4 columns: vlm, vmerge, the activation
189	// broadcast, and the dot itself. v3 swaps the strided broadcast for lw+vmv.v.x;
190	// nodot additionally replaces the dot with a plain vadd (WRONG results, timing
191	// only). v2-v3 = broadcast cost, v3-nodot = nds.vd4dots cost.
192	#define D4_TILE16_BC(DOT0, DOT1, DOT2, DOT3, acc0, acc1, planes, acts)     \
193	    asm volatile(                                                          \
194	        "vsetvli t0, zero, e8, m2, ta, ma\n\t"                             \
195	        "mv      t1, %2\n\t"                                               \
196	        "vmv.v.i v2, -1\n\t"                                               \
197	        "vlm.v   v0, (t1)\n\t"                                             \
198	        "vmerge.vim v4, v2, 1, v0\n\t"                                     \
199	        "addi    t1, t1, 32\n\t"                                           \
200	        "vlm.v   v0, (t1)\n\t"                                             \
201	        "vmerge.vim v6, v2, 1, v0\n\t"                                     \
202	        "addi    t1, t1, 32\n\t"                                           \
203	        "vlm.v   v0, (t1)\n\t"                                             \
204	        "vmerge.vim v8, v2, 1, v0\n\t"                                     \
205	        "addi    t1, t1, 32\n\t"                                           \
206	        "vlm.v   v0, (t1)\n\t"                                             \
207	        "vmerge.vim v10, v2, 1, v0\n\t"                                    \
208	        "vsetvli t0, zero, e32, m2, ta, ma\n\t"                            \
209	        "lw      t3, 0(%3)\n\t"                                            \
210	        "vmv.v.x v12, t3\n\t"                                              \
211	        "lw      t3, 4(%3)\n\t"                                            \
212	        "vmv.v.x v14, t3\n\t"                                              \
213	        "lw      t3, 8(%3)\n\t"                                            \
214	        "vmv.v.x v16, t3\n\t"                                              \
215	        "lw      t3, 12(%3)\n\t"                                           \
216	        "vmv.v.x v18, t3\n\t"                                              \
217	        DOT0 DOT1 DOT2 DOT3                                                \
218	        : "+vr"(acc0), "+vr"(acc1)                                         \
219	        : "r"(planes), "r"(acts)                                           \
220	        : "t0", "t1", "t3",                                                \
221	          "v0", "v2", "v4", "v6", "v8", "v10", "v12", "v14", "v16", "v18")
222	
223	#define D4_REAL0 "nds.vd4dots.vv %0, v4,  v12\n\t"
224	#define D4_REAL1 "nds.vd4dots.vv %1, v6,  v14\n\t"
225	#define D4_REAL2 "nds.vd4dots.vv %0, v8,  v16\n\t"
226	#define D4_REAL3 "nds.vd4dots.vv %1, v10, v18"
227	#define D4_FAKE0 "vadd.vv %0, %0, v4\n\t"
228	#define D4_FAKE1 "vadd.vv %1, %1, v6\n\t"
229	#define D4_FAKE2 "vadd.vv %0, %0, v8\n\t"
230	#define D4_FAKE3 "vadd.vv %1, %1, v10"
231	
232	#define D4_BODY(NAME, T0, T1, T2, T3)                                                        \
233	void NAME(int n, float * s, const block_q1_0_64d4 * bricks, const block_q8_0 * y,            \
234	          const int8_t * ya, int nr) {                                                       \
235	    const int nb = n / QK1_0;                                                                \
236	    const size_t vl32 = Q1_NX1_N;                                                            \
237	    for (int g = 0; g < nr / Q1_NX1_N; ++g) {                                                \
238	        const block_q1_0_64d4 * bx = bricks + (size_t)g * nb;                                \
239	        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl32);                              \
240	        for (int ib = 0; ib < nb; ++ib) {                                                    \
241	            const vfloat32m2_t dx = d4_expand_fp16_64(bx[ib].d);                             \
242	            vfloat32m2_t facc = __riscv_vfmv_v_f_f32m2(0.0f, vl32);                          \
243	            for (int k = 0; k < 4; ++k) {                                                    \
244	                const block_q8_0 * yb = &y[ib * 4 + k];                                      \
245	                const float dy = lab_fp16_to_fp32(yb->d);                                    \
246	                const int8_t * aq = ya + (ib * 4 + k) * QK8_0;                               \
247	                vint32m2_t acc0 = __riscv_vmv_v_x_i32m2(0, vl32);                            \
248	                vint32m2_t acc1 = acc0;                                                      \
249	                D4_TILE16_BC(T0, T1, T2, T3, acc0, acc1, &bx[ib].qs[k * (QK8_0/4)][0], aq);  \
250	                D4_TILE16_BC(T0, T1, T2, T3, acc0, acc1,                                     \
251	                             &bx[ib].qs[k * (QK8_0/4) + 4][0], aq + 16);                     \
252	                const vint32m2_t acc = __riscv_vadd_vv_i32m2(acc0, acc1, vl32);              \
253	                facc = __riscv_vfmacc_vf_f32m2(facc, dy,                                     \
254	                           __riscv_vfcvt_f_x_v_f32m2(acc, vl32), vl32);                      \
255	            }                                                                                \
256	            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl32);                            \
257	        }                                                                                    \
258	        __riscv_vse32_v_f32m2(s + (size_t)g * Q1_NX1_N, sumf, vl32);                         \
259	    }                                                                                        \
260	}
261	
262	D4_BODY(q1_0_gemv_64d4_v3,    D4_REAL0, D4_REAL1, D4_REAL2, D4_REAL3)
263	D4_BODY(q1_0_gemv_64d4_nodot, D4_FAKE0, D4_FAKE1, D4_FAKE2, D4_FAKE3)
