265	#else
266	
267	void q1_0_gemv_64d4(int n, float * s, const block_q1_0_64d4 * bricks, const block_q8_0 * y, const int8_t * ya, int nr) {
268	    (void)bricks; (void)y; (void)ya; (void)n;
269	    for (int i = 0; i < nr; ++i) s[i] = 0.0f;   // VLEN=512 needs m4 lanes; not built
270	}
271	
