                        acc1 = q1_vd4dots_m2(acc1, w, q1_bcast_act4(a1[c / 4], vl32));
                        acc2 = q1_vd4dots_m2(acc2, w, q1_bcast_act4(a2[c / 4], vl32));
                        acc3 = q1_vd4dots_m2(acc3, w, q1_bcast_act4(a3[c / 4], vl32));
